def transform(grid):
    h, w = len(grid), len(grid[0])
    rows = {r for r in range(h) if grid[r][0] == 1 and grid[r][w-1] == 1}
    cols = {c for c in range(w) if grid[0][c] == 1 and grid[h-1][c] == 1}
    out = [row[:] for row in grid]
    seen=set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2 and (r in rows or c in cols):
                stack=[(r,c)]; seen.add((r,c))
                while stack:
                    x,y=stack.pop(); out[x][y]=1
                    for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                        if 0<=a<h and 0<=b<w and grid[a][b]==2 and (a,b) not in seen:
                            seen.add((a,b)); stack.append((a,b))
    for r in rows:
        for c in range(w): out[r][c]=1
    for c in cols:
        for r in range(h): out[r][c]=1
    return out
